import sys
import re

# Increase recursion depth just in case of deep dependency chains
sys.setrecursionlimit(20000)

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Tokenizer patterns
    # Tokens:
    # Cell range: [A-Z][1-9][0-9]*:[A-Z][1-9][0-9]*
    # Operators / comparisons: <=, >=, <>, <, >, =
    # Arithmetic / punctuation: +, -, *, /, (, ), ,
    # Identifiers: SUM, MIN, MAX, IF, or cell name like [A-Z][1-9][0-9]*
    # Integer literal: [0-9]+

    TOKEN_REGEX = re.compile(
        r'\s*('
        r'[A-Z][1-9][0-9]*:[A-Z][1-9][0-9]*'  # Range
        r'|<=|>=|<>'                          # 2-char comparisons
        r'|[=+\-*/(),<>]'                      # Single char ops & punctuation
        r'|[A-Z][1-9][0-9]*'                  # Cell name
        r'|[A-Z]+'                            # Function name like SUM, MIN, MAX, IF
        r'|[0-9]+'                            # Integer literal
        r')'
    )

    def tokenize(s: str):
        tokens = []
        pos = 0
        n = len(s)
        while pos < n:
            m = TOKEN_REGEX.match(s, pos)
            if not m:
                # Skip any remaining whitespace
                if s[pos].isspace():
                    pos += 1
                    continue
                break
            tokens.append(m.group(1))
            pos = m.end()
        return tokens

    # AST Nodes
    class IntLit:
        __slots__ = ('val',)
        def __init__(self, val: int):
            self.val = val

    class CellRef:
        __slots__ = ('name',)
        def __init__(self, name: str):
            self.name = name

    class UnaryOp:
        __slots__ = ('op', 'operand')
        def __init__(self, op: str, operand):
            self.op = op
            self.operand = operand

    class BinOp:
        __slots__ = ('op', 'left', 'right')
        def __init__(self, op: str, left, right):
            self.op = op
            self.left = left
            self.right = right

    class RangeNode:
        __slots__ = ('start_col', 'start_row', 'end_col', 'end_row')
        def __init__(self, c1, r1, c2, r2):
            self.start_col = min(c1, c2)
            self.end_col = max(c1, c2)
            self.start_row = min(r1, r2)
            self.end_row = max(r1, r2)

    class FuncCall:
        __slots__ = ('name', 'args')
        def __init__(self, name: str, args: list):
            self.name = name
            self.args = args

    class IfNode:
        __slots__ = ('left', 'op', 'right', 'then_expr', 'else_expr')
        def __init__(self, left, op, right, then_expr, else_expr):
            self.left = left
            self.op = op
            self.right = right
            self.then_expr = then_expr
            self.else_expr = else_expr

    def parse_cell_name(s: str):
        # s is like 'A1' or 'B12'
        col = ord(s[0]) - ord('A')
        row = int(s[1:])
        return col, row

    def parse_formula(tokens: list):
        idx = 0
        n = len(tokens)

        def peek():
            return tokens[idx] if idx < n else None

        def consume(expected=None):
            nonlocal idx
            tok = tokens[idx]
            if expected is not None and tok != expected:
                raise ValueError(f"Expected {expected}, got {tok}")
            idx += 1
            return tok

        # Grammar:
        # expr: term (( '+' | '-' ) term)*
        # term: factor (( '*' | '/' ) factor)*
        # factor: '-' factor | atom
        # atom: INT | CellRef | '(' expr ')' | FuncCall

        def parse_expr():
            node = parse_term()
            while peek() in ('+', '-'):
                op = consume()
                right = parse_term()
                node = BinOp(op, node, right)
            return node

        def parse_term():
            node = parse_factor()
            while peek() in ('*', '/'):
                op = consume()
                right = parse_factor()
                node = BinOp(op, node, right)
            return node

        def parse_factor():
            if peek() == '-':
                op = consume()
                operand = parse_factor()
                return UnaryOp(op, operand)
            return parse_atom()

        def parse_atom():
            tok = peek()
            if tok == '(':
                consume('(')
                node = parse_expr()
                consume(')')
                return node

            if tok and tok.isdigit():
                consume()
                return IntLit(int(tok))

            # Function calls: SUM, MIN, MAX, IF
            if tok in ('SUM', 'MIN', 'MAX', 'IF'):
                fname = consume()
                consume('(')
                if fname == 'IF':
                    # IF(left OP right, then, else)
                    left = parse_expr()
                    op = consume()  # =, <>, <, <=, >, >=
                    right = parse_expr()
                    consume(',')
                    then_expr = parse_expr()
                    consume(',')
                    else_expr = parse_expr()
                    consume(')')
                    return IfNode(left, op, right, then_expr, else_expr)
                else:
                    # SUM, MIN, MAX take one or more args: range or formula
                    args = []
                    while True:
                        t = peek()
                        if t and ':' in t:
                            # It's a range token X1:Y2
                            range_tok = consume()
                            p1, p2 = range_tok.split(':')
                            c1, r1 = parse_cell_name(p1)
                            c2, r2 = parse_cell_name(p2)
                            args.append(RangeNode(c1, r1, c2, r2))
                        else:
                            args.append(parse_expr())
                        if peek() == ',':
                            consume(',')
                        else:
                            break
                    consume(')')
                    return FuncCall(fname, args)

            # Otherwise must be cell reference
            consume()
            return CellRef(tok)

        return parse_expr()

    # Pre-parse contents
    parsed_cells = {}
    for name, content in cells.items():
        content_stripped = content.strip()
        if not content_stripped.startswith('='):
            # Integer literal
            parsed_cells[name] = IntLit(int(content_stripped))
        else:
            tokens = tokenize(content_stripped[1:])
            parsed_cells[name] = parse_formula(tokens)

    # State for evaluation:
    # 0 = not evaluated, 1 = in progress, 2 = done
    state = {}
    values = {}

    def trunc_div(a: int, b: int) -> int:
        if (a < 0) ^ (b < 0) and a % b != 0:
            return a // b + 1
        return a // b

    def eval_node(node):
        # Returns int or error str
        if isinstance(node, IntLit):
            return node.val

        if isinstance(node, CellRef):
            ref_name = node.name
            if ref_name not in cells:
                return 0
            s = state.get(ref_name, 0)
            if s == 1:
                return "#CYCLE!"
            if s == 2:
                return values[ref_name]
            # Otherwise evaluate cell
            return eval_cell(ref_name)

        if isinstance(node, UnaryOp):
            val = eval_node(node.operand)
            if isinstance(val, str):
                return val
            return -val

        if isinstance(node, BinOp):
            lval = eval_node(node.left)
            if isinstance(lval, str):
                return lval
            rval = eval_node(node.right)
            if isinstance(rval, str):
                return rval
            if node.op == '+':
                return lval + rval
            if node.op == '-':
                return lval - rval
            if node.op == '*':
                return lval * rval
            if node.op == '/':
                if rval == 0:
                    return "#DIV/0!"
                return trunc_div(lval, rval)

        if isinstance(node, IfNode):
            lval = eval_node(node.left)
            if isinstance(lval, str):
                return lval
            rval = eval_node(node.right)
            if isinstance(rval, str):
                return rval
            cond = False
            if node.op == '=':
                cond = (lval == rval)
            elif node.op == '<>':
                cond = (lval != rval)
            elif node.op == '<':
                cond = (lval < rval)
            elif node.op == '<=':
                cond = (lval <= rval)
            elif node.op == '>':
                cond = (lval > rval)
            elif node.op == '>=':
                cond = (lval >= rval)

            if cond:
                return eval_node(node.then_expr)
            else:
                return eval_node(node.else_expr)

        if isinstance(node, FuncCall):
            collected = []
            for arg in node.args:
                if isinstance(arg, RangeNode):
                    # Evaluate cells in row-major order: top row first, left to right within row
                    for r in range(arg.start_row, arg.end_row + 1):
                        for c in range(arg.start_col, arg.end_col + 1):
                            cell_name = f"{chr(ord('A') + c)}{r}"
                            if cell_name in cells:
                                s = state.get(cell_name, 0)
                                if s == 1:
                                    return "#CYCLE!"
                                elif s == 2:
                                    val = values[cell_name]
                                else:
                                    val = eval_cell(cell_name)
                                if isinstance(val, str):
                                    return val
                                collected.append(val)
                else:
                    # Formula argument
                    val = eval_node(arg)
                    if isinstance(val, str):
                        return val
                    collected.append(val)

            if node.name == 'SUM':
                return sum(collected) if collected else 0
            elif node.name == 'MIN':
                return min(collected) if collected else 0
            elif node.name == 'MAX':
                return max(collected) if collected else 0

    def eval_cell(name: str):
        state[name] = 1
        res = eval_node(parsed_cells[name])
        values[name] = res
        state[name] = 2
        return res

    for name in cells:
        if state.get(name, 0) == 0:
            eval_cell(name)

    return values
